<template>
  <div class="home-header-container">
    <slot name="left"></slot>
    <slot name="center">
      <div class="home-header-title" @click="goHome">{{ systemTitle }}</div>
    </slot>
    <slot name="right">
      <div class="vip-info" v-if="vip">
        <el-dropdown trigger="click" @command="handleCommand">
          <img :src="vip.avatar_full" :alt="vip.nickname" />
          <el-dropdown-menu slot="dropdown">
            <el-dropdown-item icon="el-icon-picture" command="product"
              >全景作品</el-dropdown-item
            >
            <el-dropdown-item icon="el-icon-user" command="info"
              >个人资料</el-dropdown-item
            >
            <el-dropdown-item icon="el-icon-turn-off" command="logout"
              >退出</el-dropdown-item
            >
          </el-dropdown-menu>
        </el-dropdown>
      </div>
    </slot>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'LayoutHeader',
  data() {
    return {
      vipInfo: null,
    }
  },
  computed: {
    ...mapGetters(['vip', 'systemTitle'])
  },
  methods: {
    ...mapActions('user', ['logout']),
    handleCommand(command) {
      if (command === 'info') {
        return this.$router.push('/vip/info')
      }

      if (command === 'product') {
        return this.$router.push('/vip/products')
      }

      if (command === 'logout') {
        return this.$confirm('确定要退出吗?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
        })
          .then(() => {
            this.logout().then(() => {
              this.$router.push('/')
            })
          })
          .catch(() => {})
      }
    },
    goHome() {
      return this.$router.push('/')
    }
  },
}
</script>
<style lang="less" scoped>
.home-header-container {
  .vip-info {
    img {
      width: 40px;
      height: 40px;
      display: block;
      border-radius: 50%;
      object-fit: cover;
      cursor: pointer;
    }
  }
}
</style>